require_once __DIR__.'/legacy-migration/WorkforceCatalogReconciliationCandidate.php';
function reconciliationEnv(string$n):string{$v=getenv($n);if($v===false||$v==='')throw new RuntimeException("Missing {$n}");return$v;}
$path=$argv[1]??null;$apply=in_array('--apply',$argv,true);if(!is_string($path)||!is_file($path))throw new InvalidArgumentException('Usage: php reconcile-workforce-catalog-candidate.php <reviewed-evidence.json> [--apply]');$input=json_decode((string)file_get_contents($path),true,flags:JSON_THROW_ON_ERROR);$evaluation=WorkforceCatalogReconciliationCandidate::evaluate($input['legacyMatches']??[],$input['bitrixMatches']??[],$input['localRows']??[],reconciliationEnv('FMONITOR_WORKFORCE_TARGET_HASH'),reconciliationEnv('FMONITOR_PROFILE_HASH_KEY'));$public=array_diff_key($evaluation,['candidate'=>true]);if(!$apply){echo json_encode(['mode'=>'dry-run']+$public,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";exit($evaluation['eligible']?0:2);}if(!($evaluation['eligible']??false))throw new DomainException('WORKFORCE_RECONCILIATION_APPLY_NOT_ALLOWED');$prefix=reconciliationEnv('FMONITOR_TABLE_PREFIX');$db=new mysqli(getenv('FMONITOR_DB_HOST')?:'127.0.0.1',getenv('FMONITOR_DB_USER')?:'fmonitor2_demo',getenv('FMONITOR_DB_PASSWORD')?:'fmonitor2_demo_local',getenv('FMONITOR_DB_NAME')?:'fmonitor2_demo',(int)(getenv('FMONITOR_DB_PORT')?:23306));$db->set_charset('utf8mb4');try{$result=WorkforceCatalogReconciliationCandidate::apply($db,$prefix,$evaluation,reconciliationEnv('FMONITOR_OPERATION_ID'),reconciliationEnv('FMONITOR_OBSERVED_AT'));echo json_encode(['mode'=>'apply']+$result+['identifiersExposed'=>false],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";}finally{$db->close();}
